def solve(data):
    packages = data['packages']
    roots = data['roots']
    names = sorted(packages)

    if any(name not in packages for name in roots):
        return {'error': 'unsatisfiable'}

    best_versions = None
    best_vector = None

    def search(assigned, required):
        nonlocal best_versions, best_vector

        unresolved = required - assigned.keys()
        if not unresolved:
            vector = tuple(assigned.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = assigned
            return

        name = min(unresolved)
        interval = roots.get(name)
        low, high = interval if interval is not None else (None, None)

        for row in options(packages[name], low, high):
            next_assigned = dict(assigned)
            next_assigned[name] = row['version']
            next_required = required | set(row.get('deps', []))
            search(next_assigned, next_required)

    search({}, set(roots))
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}
